<?php use App\Core\Csrf; use App\Core\View; $edit=isset($habit['habit_id']); $days=['0'=>'Sunday','1'=>'Monday','2'=>'Tuesday','3'=>'Wednesday','4'=>'Thursday','5'=>'Friday','6'=>'Saturday']; ?>
<section class="page-heading"><div><p class="page-eyebrow">Habit tracker</p><h1><?= $edit?'Edit Habit':'Add Habit' ?></h1><p class="page-subtitle">Define a routine you want to make consistent.</p></div><a class="btn btn-outline-secondary" href="<?= View::e($baseUrl) ?>/habit"><i class="bi bi-arrow-left"></i> Back</a></section><?php foreach($errors as$error): ?><div class="app-flash flash-error"><i class="bi bi-exclamation-circle-fill"></i><?= View::e($error) ?></div><?php endforeach; ?><section class="form-panel"><form method="post" action="<?= View::e($baseUrl) ?>/habit/<?= $edit?'update':'store' ?>"><input type="hidden" name="_csrf" value="<?= View::e(Csrf::token()) ?>"><?php if($edit): ?><input type="hidden" name="habit_id" value="<?= (int)$habit['habit_id'] ?>"><?php endif; ?><div class="row g-4"><div class="col-12"><label class="form-label" for="habit_name">Habit Name <span class="text-danger">*</span></label><input class="form-control" id="habit_name" name="habit_name" value="<?= View::e($habit['habit_name']??'') ?>" required placeholder="e.g. Drink 2L water"></div><div class="col-md-6"><label class="form-label" for="frequency">Frequency <span class="text-danger">*</span></label><select class="form-select" id="frequency" name="frequency"><?php foreach(['Daily','Weekly','Monthly']as$x): ?><option <?= ($habit['frequency']??'Daily')===$x?'selected':'' ?>><?= $x ?></option><?php endforeach; ?></select></div><div class="col-md-6"><label class="form-label" for="status">Status <span class="text-danger">*</span></label><select class="form-select" id="status" name="status"><?php foreach(['Active','Completed']as$x): ?><option <?= ($habit['status']??'Active')===$x?'selected':'' ?>><?= $x ?></option><?php endforeach; ?></select></div><div class="col-md-6"><label class="form-label" for="schedule_time">Preferred schedule time <span class="text-muted">(optional)</span></label><input class="form-control" id="schedule_time" type="time" name="schedule_time" value="<?= View::e(isset($habit['schedule_time'])?substr((string)$habit['schedule_time'],0,5):'') ?>"></div><div class="col-md-6"><label class="form-label" for="schedule_day">Preferred day <span class="text-muted">(optional)</span></label><select class="form-select" id="schedule_day" name="schedule_day"><option value="">Any day</option><?php foreach($days as $value=>$label): ?><option value="<?= $value ?>" <?= isset($habit['schedule_day'])&&(string)$habit['schedule_day']===$value?'selected':'' ?>><?= $label ?></option><?php endforeach; ?></select></div></div><div class="form-actions"><a class="btn btn-outline-secondary" href="<?= View::e($baseUrl) ?>/habit">Cancel</a><button class="btn btn-primary"><i class="bi bi-check2-circle"></i> Save Habit</button></div></form></section>
